/* TalentFlow ATS — original, dependency-free SPA client. Real operations use the API. */
const $=(s,p=document)=>p.querySelector(s);
const $$=(s,p=document)=>[...p.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(n||0);
const date=s=>{if(!s)return '—';const d=new Date(s);return isNaN(d.getTime())?s:d.toLocaleDateString('pt-BR')};
const fmt=n=>Number(n||0).toLocaleString('pt-BR');
const humanRole={admin:'Administrador',recruiter:'Recrutador',manager:'Gestor de vaga',interviewer:'Entrevistador',candidate:'Candidato'};
const statusLabel={pending:'Pendente',approved:'Aprovado',vacation:'Férias',personal:'Pessoal',medical:'Saúde',other:'Outro',open:'Aberta',approval:'Em aprovação',closed:'Fechada',archived:'Arquivada',active:'Ativa',hired:'Contratado',rejected:'Reprovado',draft:'Rascunho',sent:'Enviada',accepted:'Aceita',declined:'Recusada',scheduled:'Agendada',confirmed:'Confirmada',completed:'Realizada',canceled:'Cancelada',no_show:'Não compareceu'};
const state={user:null,company:'',route:location.pathname,job:null,application:null,drawerTab:'resumo',jobTab:'kanban',query:'',source:'',loading:false,mobileOpen:false,csrf:null};
let overlay=null;
async function api(path,opt={}){let options={credentials:'same-origin',headers:{'Content-Type':'application/json',...(state.csrf?{'X-TF-CSRF':state.csrf}:{})},...opt};if(opt.body&&typeof opt.body!=='string')options.body=JSON.stringify(opt.body);let res;try{res=await fetch('/api'+path,options);}catch{throw new Error('Não foi possível acessar o servidor.');}let body=await res.json().catch(()=>null);if(!res.ok){if(res.status===401&&state.user){state.user=null;state.csrf=null;go('/login');}throw new Error(typeof body?.detail==='string'?body.detail:'Não foi possível completar a solicitação.');}return body;}
function toast(s,error=false){const t=$('#toast');t.innerHTML=`<div class="toast ${error?'error':''}">${esc(s)}</div>`;clearTimeout(toast._t);toast._t=setTimeout(()=>t.innerHTML='',4200)}
function go(path){if(location.pathname!==path)history.pushState({},'',path);state.route=path;if(!path.startsWith('/app/jobs/'))state.job=null;state.query='';state.jobTab='kanban';state.mobileOpen=false;closeOverlay();render()}
window.addEventListener('popstate',()=>{state.route=location.pathname;render()});
const routes=[['/app/dashboard','▦','Visão geral'],['/app/jobs','▤','Vagas'],['/app/people','♙','Colaboradores'],['/app/onboarding','◈','Integração'],['/app/learning','▧','Aprendizagem'],['/app/development','♧','Planos de desenvolvimento'],['/app/leave','⌁','Ausências e férias'],['/app/insights','◩','People Analytics'],['/app/performance','◎','Desempenho'],['/app/candidates','♙','Banco de talentos'],['/app/interviews','▣','Entrevistas'],['/app/tests','◇','Testes'],['/app/automations','⟳','Automações'],['/app/offers','▱','Propostas'],['/app/reports','▥','Relatórios'],['/app/tasks','☷','Tarefas'],['/app/audit','◷','Auditoria'],['/app/security','⚙','Sessões e segurança']];
function shell(body,title='Visão geral',sub=''){return `<a class="skip-link" href="#main-content">Ir para o conteúdo</a><div class="app"><aside class="sidebar ${state.mobileOpen?'visible':''}"><div class="brand"><div class="brandmark">↗</div><div><div class="brandname">talent<span>flow.</span></div><div class="brandmeta">PEOPLE OPERATIONS</div></div></div><div class="navcaption">TalentFlow People · Workspace</div>${routes.filter(([path])=>state.user?.role!=='candidate' && (path!='/app/audit'||state.user?.role==='admin')).map(([path,icon,name])=>`<a href="${path}" data-route="${path}" class="navlink ${state.route.startsWith(path)?'active':''}" aria-current="${state.route.startsWith(path)?'page':'false'}"><span class="nav-icon">${icon}</span>${name}</a>`).join('')}${state.user?.role==='admin'?'<a href="/workspace" class="navlink">✧ People v1.1 conectado</a>':''}<div class="navcaption">Espaço público</div><a href="/carreiras" data-route="/carreiras" class="navlink"><span class="nav-icon">↗</span>Página de carreiras</a><div class="side-foot"><div class="side-user"><span class="avatar">${esc((state.user?.name||'TF')[0])}</span><div><strong>${esc(state.user?.name||'')}</strong><span class="small">${humanRole[state.user?.role]||''}</span></div></div><button class="btn ghost sm" data-action="logout">Sair da plataforma ↗</button></div></aside><div class="main"><header class="topbar"><div class="crumb"><button class="circle-button mobilemenu" data-action="menu">☰</button><span>Workspace</span><span>›</span><b>${esc(title)}</b></div><div class="top-actions"><span class="org-pill">✦ ${esc(state.company)}</span><span class="small sub">Ambiente demonstrativo</span><button class="circle-button" data-action="tasks-shortcut" title="Tarefas">♧</button><span class="avatar">${esc((state.user?.name||'U')[0])}</span></div></header><main class="content" id="main-content">${body}</main></div></div>`}
function headline(title,description,actions=''){return `<div class="page-head"><div><div class="eyebrow">Talent acquisition / ${esc(title)}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="flex wrap">${actions}</div></div>`}
function loading(){return shell(headline('Carregando','Buscando dados em seu workspace')+`<div class="stats">${[1,2,3,4].map(()=>`<div class="panel stat"><div class="placeholder" style="width:50%"></div><div class="placeholder" style="width:70%;margin-top:20px;height:32px"></div></div>`).join('')}</div>`,'Aguarde')}
function badge(value){const text=statusLabel[value]||value||'—';const css=['open','hired','accepted','confirmed','completed','active'].includes(value)?'green':['rejected','declined','canceled','archived'].includes(value)?'red':['approval','draft','sent','scheduled'].includes(value)?'yellow':'purple';return `<span class="badge ${css}">${esc(text)}</span>`}
function fitBadge(score){return `<span class="badge ${score>=75?'green':score>=50?'yellow':'red'}">${score>=75?'Alto':score>=50?'Médio':'Baixo'} fit · ${score}%</span>`}
function avatar(name,size=''){return `<span class="avatar ${size}">${esc((name||'?').split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase())}</span>`}
function bars(items,max=8){let x=items.slice(0,max),m=Math.max(1,...x.map(v=>v.value));return `<div class="chart-list">${x.length?x.map(v=>`<div class="barrow"><span class="label" title="${esc(v.name)}">${esc(v.name)}</span><span class="bartrack"><span class="bar" style="display:block;width:${Math.round(v.value/m*100)}%"></span></span><strong>${fmt(v.value)}</strong></div>`).join(''):'<div class="empty">Ainda não há dados para este gráfico.</div>'}</div>`}
function renderLogin(){return `<div class="app-login"><section class="login-left"><div class="brand" style="padding:0"><div class="brandmark">↗</div><div><div class="brandname">talent<span>flow.</span></div><div class="brandmeta">PEOPLE OPERATIONS</div></div></div><div class="login-copy"><div class="eyebrow" style="color:#b09aff;margin-bottom:20px">Recrutamento em movimento</div><h1>Talentos certos.<br>Decisões melhores.<br>Um só lugar.</h1><p>Da primeira candidatura à contratação, seu time trabalha com mais contexto, menos ruído e processos claros.</p></div><div class="login-highlight"><div class="eyebrow" style="color:#c0afff">Seu próximo capítulo começa aqui</div><strong>100% conectado.</strong><p>Vagas, entrevistas, avaliações e propostas no mesmo fluxo.</p></div></section><section class="login-right"><form id="login-form" class="login-box"><div class="eyebrow">Bem-vindo de volta</div><h1>Entre no TalentFlow.</h1><p class="sub" style="margin:12px 0 27px">Acesse seu ambiente de recrutamento.</p><div class="field"><label for="email">E-mail profissional</label><input id="email" name="email" type="email" autocomplete="username" required/></div><div class="field"><label for="password">Senha</label><input id="password" name="password" type="password" autocomplete="current-password" required/></div><button class="btn" type="submit">Entrar no workspace <span>→</span></button><div class="demo-note"><strong>Ambiente demonstrativo</strong><br>Contas de teste disponíveis na documentação de desenvolvimento. Em produção, desabilite a carga de dados fictícios e configure autenticação real.<br><small>Não utilize dados pessoais reais neste ambiente local.</small></div></form></section></div>`}
function metric(icon,name,value,detail=''){return `<div class="panel stat"><span class="stat-icon">${icon}</span><small style="margin-top:12px">${esc(name)}</small><div class="metric">${esc(value)}</div><span class="hint">${esc(detail)}</span></div>`}
async function viewDashboard(){const d=await api('/dashboard'),m=d.metrics;return shell(headline('Visão geral','Seu panorama de recrutamento, com indicadores calculados a partir das candidaturas reais.',`<button class="btn" data-action="new-job">＋ Nova vaga</button>`)+`<div class="flex wrap" style="margin-bottom:5px"><span class="badge purple"><span class="status-dot"></span> Visão ao vivo · ${esc(state.company)}</span><span class="sub small">Atualizado ao abrir a página</span></div><div class="stats">${metric('▣','Vagas abertas',m.jobs_open,'Processos ativos')}${metric('♙','Candidaturas ativas',fmt(m.candidates_active),'Em andamento')}${metric('◎','Entrevistas agendadas',fmt(m.interviews),'Aguardando realização')}${metric('✓','Contratações',fmt(m.hired),'Concluídas no histórico')}${metric('▤','Vagas em aprovação',fmt(m.jobs_approval),'Aguardando autorização')}${metric('⌛','Tempo até contratação',m.avg_time_hire+' dias','Média histórica estimada')}${metric('↗','Conversão do funil',m.conversion+'%','Candidaturas → contratação')}${metric('☷','Atividades pendentes',fmt(m.pending_tasks),'Precisa de atenção')}</div><div class="grid2"><section class="panel"><div class="section-title"><div><h3>Candidaturas por etapa</h3><p>Distribuição atual do pipeline</p></div><span class="badge purple">Pipeline</span></div>${bars(d.stages)}</section><section class="panel"><div class="section-title"><div><h3>Origem dos talentos</h3><p>Canais de aquisição de candidaturas</p></div><span class="badge green">Aquisição</span></div>${bars(d.sources)}</section></div><div class="grid2" style="margin-top:17px"><section class="panel"><div class="section-title"><div><h3>Volume por vaga</h3><p>Vagas com maior movimentação</p></div></div>${bars(d.by_job,8)}</section><section class="panel"><div class="section-title"><div><h3>Próximas ações</h3><p>Decisões que merecem atenção</p></div></div><div style="padding:25px"><div class="choice-card"><span>◎ &nbsp; ${m.interviews} entrevistas no calendário</span><button class="btn alt sm" data-route="/app/interviews">Ver agenda →</button></div><div class="choice-card"><span>☷ &nbsp; ${m.pending_tasks} tarefas pendentes</span><button class="btn alt sm" data-route="/app/tasks">Ver tarefas →</button></div><div class="choice-card"><span>▤ &nbsp; ${m.jobs_approval} vagas para aprovação</span><button class="btn alt sm" data-route="/app/jobs">Ver vagas →</button></div><div class="note" style="margin-top:20px">Informações demonstrativas geradas por registros persistentes na base. Não correspondem a pessoas ou processos reais.</div></div></section></div>`,'Visão geral')}
async function viewJobs(){const rows=await api('/jobs'+(state.query?'?q='+encodeURIComponent(state.query):''));return shell(headline('Vagas','Organize suas posições, acompanhe o progresso e gerencie cada etapa de recrutamento.',`<button class="btn" data-action="new-job">＋ Criar vaga</button>`)+`<div class="toolbar"><div class="search">⌕ <input aria-label="Buscar vagas" placeholder="Buscar pelo nome da vaga..." value="${esc(state.query)}" data-search="jobs" /></div><span class="badge purple">${rows.length} vagas encontradas</span></div><section class="panel table-wrap"><table class="table"><thead><tr><th>Vaga</th><th>Departamento</th><th>Modelo</th><th>Candidaturas</th><th>Situação</th><th>Prazo</th><th>Ações</th></tr></thead><tbody>${rows.map(j=>`<tr><td class="clickable" data-route="/app/jobs/${j.id}"><div class="jobtitle">${esc(j.title)}<small>${esc(j.code)} · ${esc(j.location)}</small></div></td><td>${esc(j.department)}</td><td>${esc(j.modality)}</td><td><b>${fmt(j.applications)}</b></td><td>${badge(j.status)}</td><td>${date(j.due_date)}</td><td><button class="btn alt sm" data-route="/app/jobs/${j.id}">Abrir →</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Nenhuma vaga encontrada. Crie a primeira vaga para começar.</td></tr>'}</tbody></table></section>`,'Vagas')}
async function viewJob(jobId){let d=await api('/jobs/'+jobId);state.job=d;const j=d.job;const stageCount=Object.fromEntries(d.stages.map(s=>[s.id,d.applications.filter(a=>a.stage_id==s.id).length]));let filter=state.query.toLowerCase();let shown=d.applications.filter(a=>!filter||a.candidate.name.toLowerCase().includes(filter)||a.candidate.skills.toLowerCase().includes(filter));const board=d.stages.map(s=>`<section class="lane" data-drop-stage="${s.id}"><div class="lane-title"><h3>${esc(s.name)}</h3><span class="lanecount">${stageCount[s.id]}</span></div>${shown.filter(a=>a.stage_id==s.id).map(a=>`<article tabindex="0" role="button" aria-label="Abrir candidatura de ${esc(a.candidate.name)}" class="candidate-card" draggable="true" data-drag-app="${a.id}" data-open-app="${a.id}"><div class="person">${avatar(a.candidate.name)}<div><strong>${esc(a.candidate.name)}</strong><small>${esc(a.candidate.title||'Candidato')}</small></div></div><div class="card-info"><span>♧ ${esc(a.candidate.location||'Não informado')}</span><span class="fit ${a.fit<50?'low':a.fit<75?'med':''}">${a.fit}% fit</span></div><div class="tagline"><span class="microtag">${esc(a.candidate.source)}</span><span class="microtag">${a.candidate.experience_years} anos exp.</span></div><div class="card-info" style="margin-top:13px;margin-bottom:0"><span>Candidatura ${date(a.applied_at)}</span><span>↗</span></div></article>`).join('')||'<div class="candidate-empty">Nenhum candidato nesta etapa</div>'}</section>`).join('');
return shell(`<div class="crumb" style="margin-bottom:18px"><a class="crumb-link" data-route="/app/jobs">← Todas as vagas</a><span>›</span>${esc(j.code)}</div><div class="jobbanner"><div><div class="flex wrap">${badge(j.status)}<span class="small sub">${esc(j.code)} · ${esc(j.department)}</span></div><h2>${esc(j.title)}</h2><div class="small sub">♧ ${esc(j.location)} &nbsp; · &nbsp; ${esc(j.modality)} &nbsp; · &nbsp; ${esc(j.seniority)} &nbsp; · &nbsp; ${j.applications} candidaturas</div></div><div class="flex wrap">${j.status==='approval'?'<button class="btn sm" data-action="approve-job">✓ Aprovar vaga</button><button class="btn alt sm" data-action="reject-job">Reprovar vaga</button>':''}<button class="btn alt" data-action="edit-job">✎ Editar vaga</button><button class="btn alt" data-action="duplicate-job">⧉ Duplicar</button><button class="btn" data-action="add-to-job">＋ Adicionar talento</button></div></div><div class="tabs">${[['kanban','Pipeline de talentos'],['details','Sobre a vaga'],['analytics','Analytics']].map(([id,label])=>`<button class="tab ${state.jobTab===id?'active':''}" data-job-tab="${id}">${label}</button>`).join('')}</div>${state.jobTab==='details'?`<div class="panel" style="padding:26px;max-width:800px"><h2>Sobre esta oportunidade</h2><p style="margin:16px 0">${esc(j.description)}</p><h3>Requisitos</h3><p>${esc(j.requirements)}</p><h3 style="margin-top:17px">Benefícios</h3><p>${esc(j.benefits)}</p><hr class="line"><div class="kv"><div><small>Remuneração</small><b>${money(j.salary_min)} – ${money(j.salary_max)}</b></div><div><small>Posições</small><b>${j.positions}</b></div></div><hr class="line"><button class="btn" data-action="add-stage">＋ Adicionar etapa ao pipeline</button></div>`:state.jobTab==='analytics'?`<div class="grid2"><section class="panel"><div class="section-title"><h3>Candidaturas por etapa</h3></div>${bars(d.stages.map(s=>({name:s.name,value:stageCount[s.id]})))}</section><section class="panel" style="padding:25px"><h3>Visão da vaga</h3><div class="stats" style="grid-template-columns:1fr 1fr">${metric('♙','Candidaturas',d.applications.length)}${metric('◎','Fit médio',Math.round(d.applications.reduce((v,a)=>v+a.fit,0)/Math.max(1,d.applications.length))+'%')}</div></section></div>`:`<div class="toolbar"><div class="search">⌕ <input aria-label="Pesquisar candidatos no pipeline" placeholder="Pesquisar nome ou habilidade..." value="${esc(state.query)}" data-search="pipeline" /></div><span class="badge purple">${shown.length} talentos</span><button class="btn alt" data-action="add-stage">＋ Nova etapa</button></div><div class="note" style="margin-bottom:14px">Arraste os cards entre etapas. Contratação e reprovação exigem motivo e confirmação; todas as mudanças ficam auditadas.</div><div class="pipeline">${board}</div>`}`,'Vagas')}
async function viewCandidates(){const data=await api('/candidates'+(state.query?'?q='+encodeURIComponent(state.query):''));return shell(headline('Banco de talentos','Explore perfis, habilidades e históricos de pessoas candidatas.',`<button class="btn" data-action="new-candidate">＋ Novo talento</button>`)+`<div class="toolbar"><div class="search">⌕ <input data-search="candidates" placeholder="Buscar nome, cargo ou habilidade..." value="${esc(state.query)}" /></div><span class="badge purple">${data.length} perfis</span></div><section class="panel table-wrap"><table class="table"><thead><tr><th>Candidato</th><th>Localização</th><th>Experiência</th><th>Competências</th><th>Origem</th><th></th></tr></thead><tbody>${data.map(c=>`<tr class="clickable" data-open-candidate="${c.id}"><td><div class="flex">${avatar(c.name)}<div class="jobtitle">${esc(c.name)}<small>${esc(c.title||'Perfil disponível')}</small></div></div></td><td>${esc(c.location)}</td><td>${c.experience_years} anos</td><td>${esc(c.skills.slice(0,50))}</td><td>${esc(c.source)}</td><td>→</td></tr>`).join('')}</tbody></table></section>`,'Banco de talentos')}
async function viewInterviews(){const rows=await api('/interviews');return shell(headline('Entrevistas','Agende, confirme e acompanhe conversas com as pessoas candidatas.',`<button class="btn" data-route="/app/jobs">↗ Abrir pipeline</button>`)+`<div class="panel table-wrap"><table class="table"><thead><tr><th>Pessoa candidata</th><th>Data e hora</th><th>Duração</th><th>Status</th><th>Ações</th></tr></thead><tbody>${rows.map(i=>`<tr><td class="jobtitle">${esc(i.candidate)}</td><td>${esc(i.starts_at.replace('T',' · '))}</td><td>${i.duration_minutes} minutos</td><td>${badge(i.status)}</td><td><button class="btn alt sm" data-open-app="${i.application_id}">Ver candidatura</button> ${i.status==='scheduled'?`<button class="btn sm" data-confirm-interview="${i.id}">Confirmar</button>`:''}</td></tr>`).join('')}</tbody></table></div>`,'Entrevistas')}
async function viewAutomations(){const [items,runs]=await Promise.all([api('/automations'),api('/automation-runs')]);return shell(headline('Automações','Transforme movimentações do pipeline em ações consistentes e rastreáveis.',`<button class="btn" data-action="new-automation">＋ Nova automação</button>`)+`<div class="grid2"><section class="panel"><div class="section-title"><h3>Fluxos configurados</h3><span class="badge purple">${items.length} regras</span></div><div style="padding:16px">${items.map(a=>`<div class="choice-card"><div><strong>${esc(a.title)}</strong><small>QUANDO: mudança de etapa · SE: ${esc(a.condition.stage||'qualquer etapa')}<br>ENTÃO: ${esc(a.action.type||'')==='email'?'Preparar e-mail mock':'Criar tarefa'}</small><small>${a.runs} execuções</small></div><button class="btn ${a.enabled?'alt':''} sm" data-toggle-automation="${a.id}">${a.enabled?'Pausar':'Ativar'}</button></div>`).join('')||'<div class="empty">Nenhuma automação cadastrada.</div>'}</div></section><section class="panel"><div class="section-title"><h3>Histórico de execuções</h3><span class="badge green">Logs</span></div><div style="padding:22px">${runs.map(r=>`<div class="event"><strong>${r.status==='success'?'✓ Execução concluída':'! Falha de execução'}</strong><small>${esc(r.detail)} · ${date(r.at)}</small></div>`).join('')||'<div class="empty">Movimente talentos para disparar os gatilhos.</div>'}</div></section></div><p class="note" style="margin-top:18px">Ações de comunicação usam fila mock persistente: a operação aparece nos logs, mas não entrega mensagens a destinatários reais.</p>`,'Automações')}
async function viewOffers(){const rows=await api('/offers');return shell(headline('Propostas','Acompanhe ofertas de contratação, aceite e eventual recusa.')+`<section class="panel table-wrap"><table class="table"><thead><tr><th>Talento</th><th>Remuneração</th><th>Situação</th><th>Link de aceite</th><th></th></tr></thead><tbody>${rows.map(o=>`<tr><td class="jobtitle">${esc(o.candidate)}</td><td>${money(o.salary)}</td><td>${badge(o.status)}</td><td><button class="btn alt sm" data-copy="${esc(location.origin+o.accept_path)}">Copiar link</button></td><td>${o.status==='draft'?`<button class="btn sm" data-send-offer="${o.id}">Disponibilizar proposta</button>`:''}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Crie propostas dentro de uma candidatura.</td></tr>'}</tbody></table></section>`,'Propostas')}
async function viewReports(){const d=await api('/reports');return shell(headline('Relatórios','Acompanhe conversões e produtividade com informações da base persistida.',`<button class="btn alt" data-action="export-report">↓ Exportar CSV</button><button class="btn alt" data-action="print">⎙ Imprimir</button>`)+`<div class="stats">${metric('▣','Vagas abertas',d.metrics.jobs_open)}${metric('♙','Candidaturas ativas',d.metrics.candidates_active)}${metric('✓','Contratações',d.metrics.hired)}${metric('↗','Conversão',d.metrics.conversion+'%')}</div><div class="grid2"><div class="panel"><div class="section-title"><h3>Funil de seleção</h3></div>${bars(d.stages,12)}</div><div class="panel"><div class="section-title"><h3>Performance de canais</h3></div>${bars(d.sources,12)}</div></div>`,'Relatórios')}
async function viewTasks(){let items=await api('/tasks');return shell(headline('Tarefas','Atividades a executar no processo de recrutamento.')+`<div class="panel" style="padding:20px;max-width:750px">${items.map(t=>`<div class="choice-card"><div><strong style="${t.completed?'text-decoration:line-through;color:#999':''}">${esc(t.title)}</strong><small>Prazo: ${date(t.due_date)} · candidatura #${t.application_id||'—'}</small></div><button class="btn ${t.completed?'alt':''} sm" data-toggle-task="${t.id}">${t.completed?'Reabrir':'Concluir ✓'}</button></div>`).join('')||'<div class="empty">Sem tarefas cadastradas.</div>'}</div>`,'Tarefas')}
async function viewTests(){let items=await api('/tests');return shell(headline('Testes e avaliações','Crie questionários técnicos e avaliações estruturadas.',`<button class="btn" data-action="new-test">＋ Novo teste</button>`)+`<div class="grid2">${items.map(t=>`<div class="panel" style="padding:23px"><div class="flex between"><h3>${esc(t.title)}</h3><span class="badge purple">${t.questions.length} questões</span></div><p class="sub small" style="margin-top:12px">Duração: ${t.duration_minutes} minutos · Aprovação mínima: ${t.pass_percent}%</p><div class="line"></div>${t.questions.map((q,n)=>`<div class="choice-card"><span>${n+1}. ${esc(q.text)}</span><span class="badge">${esc(q.type)}</span></div>`).join('')}</div>`).join('')}</div>`,'Testes')}
async function viewAudit(){let items=await api('/audit');return shell(headline('Trilha de auditoria','Registro imutável na interface das principais alterações operacionais.')+`<section class="panel table-wrap"><table class="table"><thead><tr><th>Data</th><th>Evento</th><th>Entidade</th><th>Registro</th><th>Usuário</th></tr></thead><tbody>${items.map(a=>`<tr><td>${date(a.at)}</td><td><span class="badge purple">${esc(a.action)}</span></td><td>${esc(a.entity)}</td><td>#${a.entity_id}</td><td>${a.user_id||'Público'}</td></tr>`).join('')}</tbody></table></section>`,'Auditoria')}
async function viewCareers(){const rows=await api('/public/jobs');return `<div style="min-height:100vh;background:#f8f8fd"><div style="background:#172137;padding:24px max(25px,calc((100vw - 1140px)/2));color:white"><div class="brand" style="padding:0"><div class="brandmark">↗</div><div class="brandname">talent<span>flow.</span></div><div style="margin-left:auto"><button class="btn alt sm" data-route="/login">Área interna</button></div></div></div><main style="max-width:1140px;margin:auto;padding:70px 25px"><div class="eyebrow">Carreiras · Oportunidades</div><h1 style="max-width:720px;font-size:38px;margin:15px 0">Seu próximo desafio pode começar aqui.</h1><p class="sub" style="margin-bottom:38px">Confira oportunidades abertas e candidate-se diretamente. Os dados utilizados neste ambiente são fictícios.</p><div class="grid2">${rows.map(j=>`<div class="panel" style="padding:25px"><div class="flex between"><span class="badge green">Vaga aberta</span><span class="small sub">${esc(j.department)}</span></div><h2 style="margin:15px 0 8px">${esc(j.title)}</h2><div class="small sub">${esc(j.company)} · ${esc(j.location)} · ${esc(j.modality)}</div><p style="margin:16px 0 20px" class="sub small">${esc(j.description)}</p><button class="btn" data-apply-job="${j.id}" data-job-name="${esc(j.title)}">Candidatar-se →</button></div>`).join('')||'<div class="empty">Nenhuma vaga aberta neste momento.</div>'}</div></main></div>`}
async function viewOfferPublic(token){let o=await api('/public/offer/'+encodeURIComponent(token));return `<div class="offer-public"><section class="panel"><span class="badge purple">TalentFlow · Proposta de contratação</span><h1>${esc(o.job)}</h1><p class="sub">${esc(o.company)} convida você a fazer parte do time.</p><div class="amount">${money(o.salary)}</div><p class="sub">Início previsto: ${date(o.start_date)}<br>Benefícios: ${esc(o.benefits||'A combinar')}<br>Validade: ${date(o.expires_on)}</p><div class="line"></div>${o.status==='sent'||o.status==='viewed'?`<div class="flex wrap"><button class="btn" data-offer-respond="accepted" data-token="${esc(token)}">✓ Aceitar proposta</button><button class="btn alt" data-offer-respond="declined" data-token="${esc(token)}">Recusar</button></div>`:`<div class="note">Situação da proposta: ${esc(statusLabel[o.status]||o.status)}. A resposta já foi registrada ou a oferta ainda não está disponível.</div>`}</section></div>`}
function dialog(title,formBody,actionText,onSubmit,{danger=false,wide=false}={}){
 closeOverlay();dialog._previousFocus=document.activeElement;overlay=document.createElement('div');overlay.className='modal-backdrop';overlay.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}" style="${wide?'max-width:760px':''}"><header class="modal-head"><h2>${esc(title)}</h2><button class="close" data-close="1" aria-label="Fechar">×</button></header><form id="action-form"><div class="modal-body">${formBody}</div><footer class="modal-footer"><button class="btn alt" type="button" data-close="1">Cancelar</button><button class="btn ${danger?'danger':''}" type="submit">${esc(actionText)}</button></footer></form></section>`;document.body.appendChild(overlay);
 overlay.addEventListener('click',e=>{if(e.target===overlay||e.target.closest('[data-close]'))closeOverlay()});
 $('#action-form',overlay).addEventListener('submit',async e=>{e.preventDefault();let thisDialog=overlay;let btn=$('[type=submit]',thisDialog);btn.disabled=true;btn.textContent='Salvando...';let f=Object.fromEntries(new FormData(e.currentTarget).entries());try{await onSubmit(f);if(overlay===thisDialog)closeOverlay();await render()}catch(err){toast(err.message,true);if(btn){btn.disabled=false;btn.textContent=actionText;}}});
 setTimeout(()=>$('.field input, .field textarea, .field select',overlay)?.focus(),20);
}
function closeOverlay(){if(overlay){overlay.remove();overlay=null;dialog._previousFocus?.focus?.()}}
document.addEventListener('keydown',e=>{
  if(e.key==='Escape'&&overlay){e.preventDefault();closeOverlay();return}
  if((e.key==='Enter'||e.key===' ')&&e.target.matches('.candidate-card')){e.preventDefault();openApplication(Number(e.target.dataset.openApp));return}
  if(e.key==='Tab'&&overlay){
    const controls=[...overlay.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]')].filter(x=>x.getClientRects().length);
    if(!controls.length)return;let i=controls.indexOf(document.activeElement);
    if(e.shiftKey&&i===0){e.preventDefault();controls.at(-1).focus()}else if(!e.shiftKey&&i===controls.length-1){e.preventDefault();controls[0].focus()}
  }
});
function field(name,label,value='',type='text',extra=''){return `<div class="field"><label>${esc(label)}</label><input name="${esc(name)}" type="${type}" value="${esc(value)}" ${extra}></div>`}
function selectField(name,label,choices,selected=''){return `<div class="field"><label>${esc(label)}</label><select name="${esc(name)}">${choices.map(v=>{let [value,text]=Array.isArray(v)?v:[v,v];return `<option value="${esc(value)}" ${value==selected?'selected':''}>${esc(text)}</option>`}).join('')}</select></div>`}
function areaField(name,label,value=''){return `<div class="field full"><label>${esc(label)}</label><textarea name="${esc(name)}">${esc(value)}</textarea></div>`}
function numberOf(f,key,defaultValue=0){return Number(f[key]||defaultValue)}
function jobForm(existing=null){let j=existing||{},isEdit=!!existing;dialog(isEdit?'Editar vaga':'Nova vaga',`<div class="formgrid">${field('title','Título da vaga',j.title,'text','required minlength="3"')}${field('department','Área/departamento',j.department||'Tecnologia')}${field('location','Localização',j.location||'Brasília, DF')}${selectField('modality','Modalidade',['Híbrido','Remoto','Presencial'],j.modality||'Híbrido')}${selectField('seniority','Senioridade',['Estágio','Júnior','Pleno','Sênior','Especialista','Gestão'],j.seniority||'Pleno')}${selectField('employment','Regime',['CLT','PJ','Estágio','Temporário'],j.employment||'CLT')}${field('salary_min','Salário mínimo',j.salary_min||0,'number','min="0"')}${field('salary_max','Salário máximo',j.salary_max||0,'number','min="0"')}${field('positions','Número de posições',j.positions||1,'number','min="1"')}${field('due_date','Prazo',j.due_date||'','date')}${selectField('status','Status',[['open','Aberta'],['approval','Em aprovação'],['closed','Fechada'],['archived','Arquivada']],j.status||'open')}${areaField('description','Descrição',j.description)}${areaField('requirements','Requisitos',j.requirements)}${areaField('benefits','Benefícios',j.benefits)}</div>`,isEdit?'Salvar alterações':'Criar vaga',async f=>{const body={...f,salary_min:numberOf(f,'salary_min'),salary_max:numberOf(f,'salary_max'),positions:numberOf(f,'positions',1)};if(isEdit){await api('/jobs/'+j.id,{method:'PATCH',body});toast('Vaga atualizada.')}else{let newJob=await api('/jobs',{method:'POST',body});toast('Vaga criada com sucesso.');go('/app/jobs/'+newJob.id);}} ,{wide:true})}
function newCandidateForm(){dialog('Cadastrar novo talento',`<div class="formgrid">${field('name','Nome completo','','text','required minlength="3"')}${field('email','E-mail','','email','required')}${field('phone','Telefone')}${field('location','Localização')}${field('title','Cargo ou especialidade')}${field('experience_years','Anos de experiência',0,'number','min="0" max="80"')}${areaField('skills','Competências — separe por vírgulas')}${areaField('resume_text','Resumo profissional / currículo')}</div>`,'Salvar talento',async f=>{f.experience_years=numberOf(f,'experience_years');let c=await api('/candidates',{method:'POST',body:f});toast('Novo talento cadastrado.');if(state.job){await api('/applications',{method:'POST',body:{job_id:state.job.job.id,candidate_id:c.id}});toast('Talento vinculado à vaga.')}} ,{wide:true})}
async function addToJobForm(){let cs=await api('/candidates');let inJob=new Set(state.job.applications.map(a=>a.candidate_id));cs=cs.filter(c=>!inJob.has(c.id));dialog('Associar talento à vaga',`<div class="field"><label>Selecione uma pessoa do banco de talentos</label><select name="candidate_id" required>${cs.slice(0,200).map(c=>`<option value="${c.id}">${esc(c.name)} · ${esc(c.title)} · ${esc(c.location)}</option>`).join('')}</select></div><p class="note" style="margin-top:15px">O vínculo cria uma candidatura real no banco, posicionada na primeira etapa do pipeline.</p>`,`Vincular candidato`,async f=>{await api('/applications',{method:'POST',body:{job_id:state.job.job.id,candidate_id:Number(f.candidate_id)}});toast('Candidatura adicionada ao pipeline.')})}
function confirmAction(title,message,confirm,onConfirm){dialog(title,`<p>${esc(message)}</p>`,confirm,async()=>await onConfirm(),{danger:/Reprovar|Contratar|Recusar/i.test(confirm)})}
async function moveApp(appId,stageId){let a=state.job?.applications.find(x=>x.id==appId);let dest=state.job?.stages.find(x=>x.id==stageId);if(!a||!dest)return;
 if(dest.kind==='active'){await api('/applications/'+appId+'/move',{method:'POST',body:{stage_id:stageId}});toast(`${a.candidate.name} movido para ${dest.name}.`);await render();return;}
 dialog('Confirmar movimentação',`<p style="margin-bottom:17px">Você deseja mover <strong>${esc(a.candidate.name)}</strong> para <b>${esc(dest.name)}</b>? Essa decisão será registrada no histórico.</p>${areaField('reason','Motivo obrigatório')}`,dest.kind==='hired'?'Confirmar contratação':'Confirmar reprovação',async f=>{await api('/applications/'+appId+'/move',{method:'POST',body:{stage_id:stageId,reason:f.reason}});toast('Movimentação registrada no histórico.');})}
async function openCandidate(candidateId){let d=await api('/candidates/'+candidateId);state.job=null;const c=d.candidate;dialog('Perfil de '+c.name,`<div class="flex" style="align-items:center;margin-bottom:22px">${avatar(c.name,'big')}<div><h2>${esc(c.name)}</h2><p class="sub small">${esc(c.title||'Perfil profissional')} · ${esc(c.location)}</p></div></div><div class="kv">${[['E-mail',c.email],['Telefone',c.phone],['Experiência',c.experience_years+' anos'],['Origem',c.source],['Formação',c.education],['Competências',c.skills]].map(([k,v])=>`<div><small>${esc(k)}</small><b>${esc(v||'Não informado')}</b></div>`).join('')}</div><hr class="line"><h3>Currículo e experiências</h3><p style="white-space:pre-line;margin-top:12px">${esc(c.resume_text||'Currículo ainda não anexado.')}</p><hr class="line"><h3>Candidaturas vinculadas</h3>${d.applications.map(a=>`<div class="choice-card"><div><strong>${esc(a.job.title)}</strong><small>${esc(a.stage)} · ${a.fit}% fit</small></div><button type="button" class="btn alt sm" data-open-app="${a.id}">Abrir</button></div>`).join('')||'<p class="sub">Sem candidatura vinculada.</p>'}`,'Fechar',async()=>{},{wide:true});}
async function openApplication(id){try{state.application=await api('/applications/'+id);state.drawerTab='resumo';paintDrawer()}catch(e){toast(e.message,true)}}
function paintDrawer(){let d=state.application,a=d.application,c=a.candidate;
 const tabs=[['resumo','Resumo'],['curriculo','Currículo'],['entrevistas','Entrevistas'],['avaliacoes','Avaliações'],['comunicacao','Comunicação'],['propostas','Propostas'],['historico','Histórico']];
 closeOverlay();overlay=document.createElement('div');overlay.className='drawer-wrap';overlay.innerHTML=`<aside class="drawer" role="dialog" aria-modal="true" aria-label="Perfil do candidato"><div class="drawer-header"><div class="flex between"><span class="eyebrow">Candidatura #${a.id} · ${esc(a.job.code)}</span><button class="close" data-close="1" aria-label="Fechar">×</button></div><div class="flex" style="margin:17px 0 12px">${avatar(c.name,'big')}<div style="flex:1"><h2>${esc(c.name)}</h2><div class="small sub" style="margin-top:6px">${esc(c.title||a.job.title)} · ${esc(c.location)}</div><div class="flex" style="margin-top:8px">${fitBadge(a.fit)} ${badge(a.status)}</div></div></div><div class="tabs" style="margin:10px -2px 0">${tabs.map(([id,label])=>`<button class="tab ${state.drawerTab===id?'active':''}" data-drawer-tab="${id}">${label}</button>`).join('')}</div><div class="drawer-content">${drawerContent(d)}</div></aside>`;
 overlay.addEventListener('click',e=>{if(e.target===overlay||e.target.closest('[data-close]'))closeOverlay()});document.body.appendChild(overlay)}
function drawerContent(d){const a=d.application,c=a.candidate;
 if(state.drawerTab==='resumo')return `<div class="drawer-section"><div class="flex between"><h3>Visão do talento</h3><button class="btn alt sm" data-action="calculate-fit">↗ Reavaliar fit</button></div><div class="kv">${[['E-mail',c.email],['Telefone',c.phone],['Experiência',c.experience_years+' anos'],['Origem',c.source],['Formação',c.education],['Candidatura',date(a.applied_at)]].map(([k,v])=>`<div><small>${esc(k)}</small><b>${esc(v||'Não informado')}</b></div>`).join('')}</div><div class="line"></div><span class="small sub">Avaliação atual</span><p style="margin:7px 0 17px">${esc(a.fit_reason)}</p><button class="btn alt sm" data-action="manual-fit">✎ Revisar pontuação manualmente</button></div><div class="drawer-section"><h3>Mover no pipeline</h3>${selectField('move_stage','Próxima etapa',d.stages.map(s=>[s.id,s.name]),a.stage_id)}<button style="margin-top:12px" class="btn" data-action="move-from-drawer">Mover candidato →</button></div><div class="drawer-section"><h3>Próximas ações</h3><div class="context-menu"><button class="btn alt sm" data-drawer-tab="entrevistas">◎ Agendar entrevista</button><button class="btn alt sm" data-drawer-tab="avaliacoes">★ Scorecard</button><button class="btn alt sm" data-drawer-tab="comunicacao">✉ Comunicação</button><button class="btn alt sm" data-drawer-tab="propostas">▱ Proposta</button></div></div>`;
 if(state.drawerTab==='curriculo')return `<div class="drawer-section"><div class="flex between"><h3>Currículo registrado</h3><label class="btn alt sm" style="cursor:pointer">↑ Enviar PDF / DOC / DOCX <input type="file" id="resume-upload" accept=".pdf,.doc,.docx" style="display:none" /></label></div><p class="small sub" style="margin:10px 0">Limite 5 MB. Extração local, dados preservados por empresa.</p>${(d.resumes||[]).map(r=>`<div class="choice-card"><div><strong>${esc(r.filename)}</strong><small>${date(r.created_at)} · ${r.text_chars} caracteres extraídos</small></div><a class="btn alt sm" target="_blank" rel="noopener noreferrer" href="/api/resumes/${r.id}/download">Abrir</a></div>`).join('')}<div class="note">O texto abaixo é persistido no registro de candidatura. Extração automática de PDF/DOCX será incorporada quando o adaptador de arquivos estiver configurado.</div><div style="margin:18px 0;white-space:pre-wrap;line-height:1.9;color:#425069">${esc(c.resume_text||'Não há currículo enviado.')}</div></div><div class="drawer-section"><h3>Competências e formação</h3><p><b>Competências:</b> ${esc(c.skills)}</p><p><b>Formação:</b> ${esc(c.education)}</p><p><b>Experiência:</b> ${c.experience_years} anos</p></div>`;
 if(state.drawerTab==='entrevistas')return `<div class="flex between" style="margin-bottom:16px"><h3>Agenda de entrevistas</h3><button class="btn" data-action="schedule-interview">＋ Agendar</button></div>${d.interviews.map(v=>`<div class="drawer-section"><div class="flex between"><h3>${esc(v.starts_at.replace('T',' às '))}</h3>${badge(v.status)}</div><p class="sub small">Duração de ${v.duration_minutes} minutos · ${esc(v.notes||'Sem observações')}</p>${v.status==='scheduled'?`<button class="btn alt sm" style="margin-top:11px" data-confirm-interview="${v.id}">Confirmar presença</button>`:''}</div>`).join('')||'<div class="empty">Ainda não existem entrevistas para esta pessoa.</div>'}`;
 if(state.drawerTab==='avaliacoes')return `<div class="flex between" style="margin-bottom:16px"><h3>Scorecards</h3><button class="btn" data-action="new-scorecard">＋ Nova avaliação</button></div>${d.scorecards.map(sc=>`<div class="drawer-section"><div class="flex between"><h3>Nota final ponderada</h3><span class="badge green">${sc.result.toFixed(2)} / 5</span></div>${sc.criteria.map(i=>`<div class="flex between" style="padding:8px 0;border-bottom:1px solid #f1f1f4"><span class="small">${esc(i.name)} <span class="sub">×${i.weight}</span></span><strong>${i.score}/5</strong></div>`).join('')}<p class="sub small" style="margin-top:13px">${esc(sc.notes||'Sem comentários')}</p></div>`).join('')||'<div class="empty">Nenhum scorecard preenchido.</div>'}`;
 if(state.drawerTab==='comunicacao')return `<div class="flex between" style="margin-bottom:16px"><h3>Comunicação</h3><button class="btn" data-action="new-communication">✉ Nova mensagem</button></div>${d.communications.map(v=>`<div class="drawer-section"><div class="flex between"><h3>${esc(v.subject)}</h3><span class="badge yellow">${esc(v.status)}</span></div><p class="sub small" style="white-space:pre-wrap;margin-top:13px">${esc(v.body)}</p><p class="sub small" style="margin-top:8px">Canal: ${esc(v.channel)} · Demonstração sem envio externo</p></div>`).join('')||'<div class="empty">Nenhuma comunicação registrada.</div>'}`;
 if(state.drawerTab==='propostas')return `<div class="flex between" style="margin-bottom:16px"><h3>Cartas oferta</h3><button class="btn" data-action="new-offer">＋ Nova proposta</button></div>${d.offers.map(v=>`<div class="drawer-section"><div class="flex between"><h3>${money(v.salary)}</h3>${badge(v.status)}</div><p class="sub small" style="margin:11px 0">Início previsto: ${date(v.start_date)}</p><div class="context-menu"><button class="btn alt sm" data-copy="${esc(location.origin+'/oferta/'+v.token)}">Copiar link</button>${v.status==='draft'?`<button class="btn sm" data-send-offer="${v.id}">Disponibilizar proposta</button>`:''}</div></div>`).join('')||'<div class="empty">Nenhuma proposta ainda.</div>'}<div class="note">Ao disponibilizar a proposta, um link de aceite fica acessível. O envio de e-mail permanece em modo mock.</div>`;
 if(state.drawerTab==='historico')return `<h3 style="margin-bottom:18px">Linha do tempo da candidatura</h3><div class="timeline">${d.activities.map(v=>`<div class="event"><strong>${esc(v.description)}</strong><small>${date(v.created_at)} · ${esc(v.kind)}</small></div>`).join('')||'<div class="empty">Sem atividades registradas.</div>'}</div>`;
 return ''}
function changeDrawerTab(tab){state.drawerTab=tab;paintDrawer()}
async function drawerRefresh(tab){let id=state.application?.application.id;if(!id)return;state.application=await api('/applications/'+id);state.drawerTab=tab||state.drawerTab;paintDrawer();if(state.job){state.job=await api('/jobs/'+state.job.job.id)}}
function createInterviewForm(){const a=state.application.application;dialog('Agendar entrevista com '+a.candidate.name,`<div class="formgrid">${field('starts_at','Data e hora',new Date(Date.now()+86400000).toISOString().slice(0,16),'datetime-local','required')}${field('duration_minutes','Duração (minutos)',45,'number','min="15" max="240"')}${field('meeting_link','Link da videoconferência')}${areaField('notes','Roteiro e observações')}</div>`,'Agendar entrevista',async f=>{f.duration_minutes=numberOf(f,'duration_minutes');await api('/applications/'+a.id+'/interviews',{method:'POST',body:f});toast('Entrevista agendada e salva na agenda.');await drawerRefresh('entrevistas')})}
function createScorecardForm(){const a=state.application.application;const labels=['Comunicação','Conhecimento técnico','Capacidade analítica','Colaboração','Potencial'];dialog('Avaliar '+a.candidate.name,`<p class="small sub" style="margin-bottom:16px">Critérios personalizáveis com escala de 1 a 5 e cálculo ponderado automático.</p><div class="formgrid">${labels.map((name,i)=>`<div class="field"><label>${esc(name)} — nota</label><select name="score_${i}">${[1,2,3,4,5].map(n=>`<option value="${n}" ${n==3?'selected':''}>${n} / 5</option>`).join('')}</select></div><div class="field"><label>Peso do critério</label><input name="weight_${i}" type="number" min="1" max="10" value="${i===1?2:1}"></div>`).join('')}${areaField('notes','Parecer e evidências')}</div>`,'Registrar scorecard',async f=>{let criteria=labels.map((name,i)=>({name,weight:numberOf(f,'weight_'+i),score:numberOf(f,'score_'+i)}));let resp=await api('/applications/'+a.id+'/scorecards',{method:'POST',body:{criteria,notes:f.notes}});toast(`Avaliação salva: ${resp.result}/5.`);await drawerRefresh('avaliacoes')},{wide:true})}
function createCommunicationForm(){const a=state.application.application;dialog('Nova comunicação para '+a.candidate.name,`<div class="formgrid">${selectField('channel','Canal',[['email','E-mail (mock)'],['whatsapp','WhatsApp (mock)'],['internal','Notificação interna']])}${field('subject','Assunto','Olá, {{nome}}!','text','required')}${areaField('body','Mensagem','Olá, {{nome}}! Sobre a vaga {{vaga}}, gostaríamos de compartilhar uma atualização. Atenciosamente, {{recrutador}}.')}</div><div class="note" style="margin-top:18px">Variáveis: {{nome}}, {{vaga}}, {{empresa}}, {{recrutador}}. A comunicação será persistida em uma fila demonstrativa, sem envio externo.</div>`,'Registrar comunicação',async f=>{await api('/applications/'+a.id+'/communications',{method:'POST',body:f});toast('Mensagem registrada na fila de envio mock.');await drawerRefresh('comunicacao')})}
function createOfferForm(){const a=state.application.application;dialog('Criar proposta para '+a.candidate.name,`<div class="formgrid">${field('salary','Salário mensal (R$)',6000,'number','min="1" required')}${field('start_date','Data de início','','date')}${field('expires_on','Validade da proposta','','date')}${areaField('benefits','Benefícios','Plano de saúde, vale alimentação e desenvolvimento.')}${areaField('notes','Observações')}</div>`,'Gerar proposta',async f=>{f.salary=numberOf(f,'salary');await api('/applications/'+a.id+'/offers',{method:'POST',body:f});toast('Proposta criada como rascunho.');await drawerRefresh('propostas')})}
function manualFitForm(){const a=state.application.application;dialog('Revisar fit de '+a.candidate.name,`<div class="formgrid">${field('score','Nota (0 a 100)',a.fit,'number','min="0" max="100" required')}${areaField('reason','Justificativa da revisão humana',a.fit_reason)}</div>`,'Salvar revisão',async f=>{await api('/applications/'+a.id+'/fit',{method:'POST',body:{score:Number(f.score),reason:f.reason}});toast('Classificação revisada e auditada.');await drawerRefresh('resumo')})}
function newAutomationForm(){dialog('Criar automação',`<p class="small sub" style="margin-bottom:20px">QUANDO um talento mudar de etapa → SE estiver na etapa indicada → ENTÃO preparar comunicação automática.</p><div class="formgrid">${field('title','Nome da regra','Novo convite para entrevista','text','required')}${selectField('stage','Condição: etapa',['Novos','Triagem','Entrevista RH','Entrevista Gestor','Teste','Finalistas','Proposta','Contratado','Reprovado'])}${field('subject','Ação: assunto do e-mail','Atualização da sua candidatura')}</div><div class="note" style="margin-top:17px">As regras ficam ativas e persistidas no banco. Os e-mails são enfileirados no provedor mock.</div>`,'Ativar regra',async f=>{await api('/automations',{method:'POST',body:f});toast('Automação salva e ativada.')})}
function newTestForm(){dialog('Novo teste',`<div class="formgrid">${field('title','Título do teste','Avaliação técnica','text','required')}${field('duration_minutes','Duração (minutos)',30,'number','min="1"')}${field('pass_percent','Aprovação mínima (%)',70,'number','min="0" max="100"')}${areaField('question','Primeira questão (múltipla escolha)')}${field('option_a','Alternativa A')}${field('option_b','Alternativa B')}${field('option_c','Alternativa C')}${selectField('correct','Alternativa correta',[[0,'A'],[1,'B'],[2,'C']])}</div>`,'Criar teste',async f=>{const qs=[{text:f.question||'Questão sem enunciado',type:'multiple_choice',options:[f.option_a,f.option_b,f.option_c],correct:Number(f.correct),points:10}];await api('/tests',{method:'POST',body:{title:f.title,duration_minutes:Number(f.duration_minutes),pass_percent:Number(f.pass_percent),questions:qs}});toast('Teste criado e persistido.')})}
function newApplyForm(jobId,title){dialog('Candidatar-se: '+title,`<p class="sub small" style="margin-bottom:20px">Seus dados serão usados somente para este processo seletivo demonstrativo.</p><div class="formgrid">${field('name','Nome completo','','text','required minlength="3"')}${field('email','E-mail','','email','required')}${field('phone','Telefone')}${field('location','Cidade / UF')}${areaField('resume_text','Resumo do currículo e experiências')}<div class="field full"><label style="font-weight:500"><input name="consent" type="checkbox" required style="width:auto;min-height:0;margin-right:7px">Aceito o tratamento de meus dados para esta candidatura (LGPD).</label></div></div>`,'Enviar candidatura',async f=>{const body={...f,job_id:jobId,consent:f.consent==='on'};await api('/public/apply',{method:'POST',body});toast('Sua candidatura foi recebida com sucesso!')},{wide:true})}
async function render(){let el=$('#app'),p=location.pathname;state.route=p;
 if(p==='/login'){el.innerHTML=renderLogin();return}
 if(p==='/carreiras'){el.innerHTML='<div class="empty">Carregando oportunidades...</div>';try{el.innerHTML=await viewCareers()}catch(e){el.innerHTML=`<div class="empty">${esc(e.message)}</div>`}return}
 if(p.startsWith('/oferta/')){el.innerHTML='<div class="empty">Carregando proposta...</div>';try{el.innerHTML=await viewOfferPublic(p.split('/')[2])}catch(e){el.innerHTML=`<div class="empty">${esc(e.message)}</div>`}return}
 if(!state.user){try{let me=await api('/me');state.user=me.user;state.company=me.company;state.csrf=(await api('/auth/csrf')).token}catch(e){el.innerHTML=renderLogin();history.replaceState({},'','/login');return}}
 if(state.user.role==='candidate'){el.innerHTML=loading();try{let p=await api('/portal');let body=headline('Minhas candidaturas','Acompanhe o andamento das suas inscrições e entrevistas.',`<button class="btn" data-route="/carreiras">↗ Explorar vagas</button>`)+`<div class="grid2">${p.applications.map(a=>`<div class="panel" style="padding:24px"><div class="flex between"><h3>${esc(a.job)}</h3>${badge(a.status)}</div><p class="small sub" style="margin:9px 0">${esc(a.company)} · Inscrição em ${date(a.applied_at)}</p><div class="choice-card"><span>Etapa atual</span><strong>${esc(a.stage)}</strong></div>${a.interviews.map(i=>`<div class="choice-card"><span>Entrevista · ${date(i.starts_at)}</span>${badge(i.status)}</div>`).join('')}${a.offers.map(o=>`<div class="choice-card"><span>Proposta ${badge(o.status)}</span>${o.accept_path?`<button class="btn sm" data-route="${esc(o.accept_path)}">Visualizar →</button>`:''}</div>`).join('')}</div>`).join('')||'<div class="panel empty">Você ainda não possui candidaturas ligadas a este e-mail. Explore as oportunidades abertas!</div>'}</div>`;el.innerHTML=shell(body,'Portal do candidato')}catch(e){el.innerHTML=shell(`<div class="panel empty">${esc(e.message)}</div>`,'Portal do candidato')}return}
 el.innerHTML=loading();try{
 const routesUI={'/':viewDashboard,'/app/dashboard':viewDashboard,'/app/jobs':viewJobs,'/app/candidates':viewCandidates,'/app/interviews':viewInterviews,'/app/tests':viewTests,'/app/automations':viewAutomations,'/app/offers':viewOffers,'/app/reports':viewReports,'/app/tasks':viewTasks,'/app/audit':viewAudit,'/app/people':viewPeople,'/app/onboarding':viewOnboarding,'/app/learning':viewLearning,'/app/performance':viewPerformance,'/app/development':viewDevelopment,'/app/leave':viewLeave,'/app/insights':viewInsights,'/app/security':viewSecurity};
 if(/^\/app\/people\/\d+$/.test(p)){el.innerHTML=await viewEmployee(Number(p.split('/').pop()))}
 else if(/^\/app\/jobs\/\d+$/.test(p)){el.innerHTML=await viewJob(Number(p.split('/').pop()))}
 else if(routesUI[p]){el.innerHTML=await routesUI[p]();}
 else {el.innerHTML=shell('<div class="empty"><h3>Página não encontrada</h3><button class="btn" data-route="/app/dashboard">Voltar ao dashboard</button></div>','Não encontrado')}
 }catch(e){el.innerHTML=shell(`<div class="panel empty"><h3>Não foi possível carregar a página.</h3><p>${esc(e.message)}</p><button class="btn alt" data-action="reload" style="margin-top:15px">Tentar novamente</button></div>`,'Erro');toast(e.message,true)}
}
const navigate=p=>go(p);
document.addEventListener('submit',async e=>{
 if(e.target.id!=='login-form')return;e.preventDefault();let b=$('button[type=submit]',e.target);b.disabled=true;
 try{let r=await api('/auth/login',{method:'POST',body:{email:e.target.email.value,password:e.target.password.value}});state.user=r.user;state.csrf=(await api('/auth/csrf')).token;let m=await api('/me');state.company=m.company;toast('Bem-vindo ao TalentFlow.');go('/app/dashboard')}
 catch(err){toast(err.message,true)}finally{b.disabled=false}
});
document.addEventListener('click',async e=>{
 let t=e.target.closest('[data-route], [data-action], [data-open-app], [data-open-candidate], [data-drawer-tab], [data-job-tab], [data-toggle-task], [data-toggle-automation], [data-confirm-interview], [data-copy], [data-send-offer], [data-apply-job], [data-offer-respond]');if(!t)return;
 if(t.dataset.route){e.preventDefault();return navigate(t.dataset.route)}
 try{
 if(t.dataset.openApp){e.preventDefault();return await openApplication(Number(t.dataset.openApp))}
 if(t.dataset.openCandidate){e.preventDefault();return await openCandidate(Number(t.dataset.openCandidate))}
 if(t.dataset.drawerTab){e.preventDefault();return changeDrawerTab(t.dataset.drawerTab)}
 if(t.dataset.jobTab){e.preventDefault();state.jobTab=t.dataset.jobTab;return render()}
 if(t.dataset.toggleTask){await api('/tasks/'+t.dataset.toggleTask+'/toggle',{method:'POST'});toast('Tarefa atualizada.');return render()}
 if(t.dataset.toggleAutomation){await api('/automations/'+t.dataset.toggleAutomation+'/toggle',{method:'POST'});toast('Automação atualizada.');return render()}
 if(t.dataset.confirmInterview){await api('/interviews/'+t.dataset.confirmInterview,{method:'PATCH',body:{status:'confirmed'}});toast('Entrevista confirmada.');if(state.application)return drawerRefresh('entrevistas');return render()}
 if(t.dataset.copy){await navigator.clipboard.writeText(t.dataset.copy);return toast('Link copiado para a área de transferência.')}
 if(t.dataset.sendOffer){const r=await api('/offers/'+t.dataset.sendOffer+'/send',{method:'POST'});toast('Proposta disponibilizada; compartilhe o link de aceite.');if(state.application)return drawerRefresh('propostas');return render()}
 if(t.dataset.applyJob)return newApplyForm(Number(t.dataset.applyJob),t.dataset.jobName||'Vaga')
 if(t.dataset.offerRespond){let answer=t.dataset.offerRespond,token=t.dataset.token;return confirmAction('Responder à proposta',answer==='accepted'?'Confirma o aceite desta proposta?':'Confirma a recusa desta proposta?',answer==='accepted'?'Aceitar proposta':'Recusar proposta',async()=>{await api('/public/offer/'+encodeURIComponent(token)+'/respond',{method:'POST',body:{response:answer}});toast('Resposta à proposta registrada.');await render()})}
 let act=t.dataset.action;
 if(!act)return;
 if(act==='menu'){state.mobileOpen=!state.mobileOpen;return $('.sidebar')?.classList.toggle('visible',state.mobileOpen)}
 if(act==='reload')return render();
 if(act==='logout'){await api('/auth/logout',{method:'POST'});state.user=null;state.csrf=null;state.company='';toast('Sessão encerrada.');return go('/login')}
 if(act==='new-job')return jobForm();
 if(act==='approve-job'||act==='reject-job'){let approved=act==='approve-job';return confirmAction('Decisão sobre a vaga',approved?'Aprovar a requisição e publicar esta vaga?':'Reprovar a requisição e encerrar esta vaga?',approved?'Aprovar':'Reprovar',async()=>{await api('/jobs/'+state.job.job.id+'/approve',{method:'POST',body:{decision:approved?'approved':'rejected'}});toast('Decisão registrada.');await render()})}
 if(act==='edit-job')return jobForm(state.job.job);
 if(act==='duplicate-job')return confirmAction('Duplicar vaga','Criar uma cópia desta vaga, iniciando em aprovação?','Duplicar',async()=>{let j=await api('/jobs/'+state.job.job.id+'/duplicate',{method:'POST'});toast('Vaga duplicada.');go('/app/jobs/'+j.id)})
 if(act==='new-candidate')return newCandidateForm();
 if(act==='add-to-job')return await addToJobForm();
 if(act==='add-stage')return dialog('Adicionar etapa ao processo',field('name','Nome da nova etapa','','text','required'),'Criar etapa',async f=>{await api('/jobs/'+state.job.job.id+'/stages',{method:'POST',body:f});toast('Etapa criada no pipeline.')});
 if(act==='move-from-drawer'){let sel=$('[name=move_stage]',overlay);let app=state.application.application;let target=state.application.stages.find(s=>s.id==Number(sel.value));if(target?.kind!=='active'){
     let id=app.id,stageid=Number(sel.value);closeOverlay();dialog('Confirmar decisão',`<p style="margin-bottom:12px">Registrar movimentação de ${esc(app.candidate.name)} para ${esc(target.name)}.</p>${areaField('reason','Motivo obrigatório')}`,'Confirmar',async f=>{await api('/applications/'+id+'/move',{method:'POST',body:{stage_id:stageid,reason:f.reason}});toast('Decisão registrada no histórico.');await render()});return}
   await api('/applications/'+app.id+'/move',{method:'POST',body:{stage_id:Number(sel.value)}});toast('Etapa atualizada.');await drawerRefresh('resumo');return render()}
 if(act==='calculate-fit'){let id=state.application.application.id;let res=await api('/applications/'+id+'/fit',{method:'POST',body:{}});toast(`Análise local: ${res.label} (${res.score}%).`);return drawerRefresh('resumo')}
 if(act==='manual-fit')return manualFitForm();
 if(act==='schedule-interview')return createInterviewForm();
 if(act==='new-scorecard')return createScorecardForm();
 if(act==='new-communication')return createCommunicationForm();
 if(act==='new-offer')return createOfferForm();
 if(act==='new-automation')return newAutomationForm();
 if(act==='new-test')return newTestForm();
 if(act==='tasks-shortcut')return go('/app/tasks');
 if(act==='print')return window.print();
 if(act==='export-report'){
   let d=await api('/reports'),lines=[['Métrica','Valor'],...Object.entries(d.metrics),[],['Etapa','Candidaturas'],...d.stages.map(x=>[x.name,x.value]),[],['Origem','Candidaturas'],...d.sources.map(x=>[x.name,x.value])];
   let csv='\ufeff'+lines.map(row=>row.map(cell=>'"'+String(cell??'').replaceAll('"','""')+'"').join(';')).join('\r\n');let url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));let a=document.createElement('a');a.href=url;a.download='talentflow-relatorio.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);return toast('Relatório CSV gerado a partir do banco.');
 }
 }catch(err){toast(err.message,true)}
});
let debounce=null;
document.addEventListener('change',async e=>{if(e.target.id!=='resume-upload')return;let file=e.target.files?.[0];if(!file)return;let candidateId=state.application?.application.candidate_id;if(!candidateId)return;if(file.size>5*1024*1024){toast('O arquivo deve ter até 5 MB.',true);return}let data=new FormData();data.append('file',file);try{let r=await fetch('/api/candidates/'+candidateId+'/resume',{method:'POST',credentials:'same-origin',body:data});let json=await r.json();if(!r.ok)throw new Error(json.detail||'Falha ao enviar currículo.');toast(`Currículo processado (${json.extracted_chars} caracteres).`);await drawerRefresh('curriculo')}catch(err){toast(err.message,true)}});
document.addEventListener('input',e=>{const kind=e.target.dataset.search;if(!kind)return;clearTimeout(debounce);state.query=e.target.value;let pos=e.target.selectionStart;debounce=setTimeout(async()=>{await render();const input=$(`[data-search="${kind}"]`);if(input){input.focus();try{input.setSelectionRange(pos,pos)}catch{}}},320)});
let draggedAppId=null;
document.addEventListener('dragstart',e=>{let card=e.target.closest('[data-drag-app]');if(card){draggedAppId=Number(card.dataset.dragApp);e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',String(draggedAppId))}});
document.addEventListener('dragover',e=>{let lane=e.target.closest('[data-drop-stage]');if(lane){e.preventDefault();lane.classList.add('dragover')}});
document.addEventListener('dragleave',e=>{let lane=e.target.closest('[data-drop-stage]');if(lane&&!lane.contains(e.relatedTarget))lane.classList.remove('dragover')});
document.addEventListener('drop',async e=>{let lane=e.target.closest('[data-drop-stage]');if(!lane||!draggedAppId)return;e.preventDefault();lane.classList.remove('dragover');const id=draggedAppId;draggedAppId=null;try{await moveApp(id,Number(lane.dataset.dropStage))}catch(err){toast(err.message,true)}});
render();

/* People Lifecycle v0.4 — connected HRIS, onboarding, learning and performance views. */
function indicatorCard(label,k,unit='%'){
 const val=k.value===null?'—':(unit==='%'?`${k.value}%`:fmt(k.value));
 return `<div class="panel stat"><small>${esc(label)}</small><div class="metric">${esc(val)}</div><div class="small sub">${esc(k.description)}</div><div class="hint">${k.denominator} registros no denominador${k.suppressed?' · coorte pequena':''}</div></div>`;
}
async function viewPeople(){
 const [data,ps]=await Promise.all([api('/lifecycle/analytics'),api('/lifecycle/employees')]);let m=data.indicators;
 return shell(headline('Pessoas e indicadores','Da admissão à evolução profissional, com indicadores rastreáveis e interpretações documentadas.',`<button class="btn" data-people="create-employee">＋ Novo colaborador</button>`)+
 `<div class="note">Dados de demonstração · ${esc(data.as_of)} · Escopo: ${esc(data.scope)}. Medidas descritivas, não validação científica dos resultados.</div>`+
 `<div class="stats" style="margin-top:18px">${indicatorCard('Quadro ativo',m.active_headcount,'number')}${indicatorCard('Integração concluída',m.onboarding_completion)}${indicatorCard('Treinamentos concluídos',m.learning_completion)}${indicatorCard('Metas atingidas',m.goal_attainment)}${indicatorCard('Retenção aos 90 dias',m.retention_90d)}${indicatorCard('Rotatividade voluntária 12m',m.voluntary_turnover_12m)}</div>`+
 `<div class="grid2"><section class="panel"><div class="section-title"><div><h3>Colaboradores por área</h3><p>Vínculos ativos no período</p></div></div>${bars(data.departments)}</section><section class="panel" style="padding:24px"><h3>Como ler este painel</h3><p class="sub" style="margin-top:13px">Cada indicador apresenta numerador, denominador e metodologia. Nenhuma das taxas isoladas mede produtividade, engajamento ou eficácia causal dos programas.</p><p class="sub" style="margin-top:14px">A retenção aos 90 dias é omitida quando a coorte possui menos de 5 pessoas. Pesquisas sensíveis exigirão política de privacidade específica.</p><button class="btn alt sm" style="margin-top:14px" data-route="/app/performance">Acompanhar desempenho →</button></section></div>`+
 `<section class="panel table-wrap" style="margin-top:20px"><div class="section-title"><div><h3>Diretório de colaboradores</h3><p>Registros persistidos, segregados por empresa</p></div><span class="badge purple">${ps.length} registros</span></div><table class="table"><thead><tr><th>Nome</th><th>Área</th><th>Cargo</th><th>Admissão</th><th>Situação</th><th></th></tr></thead><tbody>${ps.map(e=>`<tr><td><strong>${esc(e.name)}</strong><small style="display:block">${esc(e.employee_code)}</small></td><td>${esc(e.department)}</td><td>${esc(e.job_title)}</td><td>${date(e.hire_date)}</td><td>${badge(e.status)}</td><td><button class="btn alt sm" data-route="/app/people/${e.id}">Abrir →</button></td></tr>`).join('')}</tbody></table></section>`,'Pessoas');
}
async function viewOnboarding(){
 const rows=await api('/lifecycle/onboarding'),pend=rows.filter(x=>!x.done),late=pend.filter(x=>x.due_date&&x.due_date<new Date().toISOString().slice(0,10));
 return shell(headline('Integração de colaboradores','Acompanhe o preparo, as boas-vindas e o desenvolvimento nos primeiros 90 dias.')+
 `<div class="stats">${metric('◈','Atividades de integração',rows.length)}${metric('✓','Concluídas',rows.length-pend.length)}${metric('⌛','Em aberto',pend.length)}${metric('!','Pendentes e vencidas',late.length)}</div>`+
 `<section class="panel table-wrap"><table class="table"><thead><tr><th>Colaborador</th><th>Etapa</th><th>Atividade</th><th>Prazo</th><th>Estado</th><th>Ação</th></tr></thead><tbody>${rows.map(x=>`<tr><td><button class="btn ghost sm" data-route="/app/people/${x.employee_id}">${esc(x.employee)}</button></td><td>${esc(x.phase)}</td><td>${esc(x.title)}</td><td>${date(x.due_date)}</td><td>${badge(x.done?'completed':'scheduled')}</td><td><button class="btn alt sm" data-people-toggle="${x.id}">${x.done?'Reabrir':'Concluir'}</button></td></tr>`).join('')}</tbody></table></section>`,'Integração');
}
async function viewLearning(){
 const [courses,enrollments,people]=await Promise.all([api('/lifecycle/courses'),api('/lifecycle/enrollments'),api('/lifecycle/employees')]);
 return shell(headline('Aprendizagem e desenvolvimento','Cursos atribuídos, competências e evidências de conclusão — sem confundir presença com aprendizado.',`<button class="btn alt" data-people="assign-course">＋ Atribuir curso</button><button class="btn" data-people="new-course">＋ Criar curso</button>`)+
 `<div class="stats">${metric('▧','Cursos disponíveis',courses.length)}${metric('♙','Inscrições',enrollments.length)}${metric('✓','Concluídas',enrollments.filter(x=>x.status==='completed').length)}${metric('⌛','Em andamento',enrollments.filter(x=>x.status!=='completed').length)}</div>`+
 `<div class="grid2"><section class="panel"><div class="section-title"><h3>Catálogo de aprendizagem</h3></div><div style="padding:16px">${courses.map(c=>`<div class="choice-card"><div><strong>${esc(c.title)}</strong><small>${esc(c.skill)} · ${esc(c.duration_hours)}h</small></div><span class="badge purple">${c.enrollments} inscrições</span></div>`).join('')}</div></section><section class="panel"><div class="section-title"><h3>Registros de aprendizagem</h3></div><div style="padding:16px">${enrollments.slice(0,45).map(e=>`<div class="choice-card"><div><strong>${esc(e.employee)}</strong><small>${esc(e.course)}</small></div>${e.status==='completed'?badge('completed'):`<button class="btn alt sm" data-people-complete="${e.id}">Concluir</button>`}</div>`).join('')}</div></section></div>`,'Aprendizagem');
}
async function viewPerformance(){
 const [goals,people]=await Promise.all([api('/lifecycle/goals'),api('/lifecycle/employees')]);
 return shell(headline('Gestão de desempenho','Objetivos observáveis, progresso e conversas estruturadas — sem ranking automático de pessoas.',`<button class="btn" data-people="new-goal">＋ Criar objetivo</button>`)+
 `<div class="stats">${metric('◎','Metas registradas',goals.length)}${metric('✓','Metas atingidas',goals.filter(g=>g.actual>=g.target).length)}${metric('⌛','A acompanhar',goals.filter(g=>g.actual<g.target).length)}</div>`+
 `<section class="panel table-wrap"><table class="table"><thead><tr><th>Colaborador</th><th>Objetivo</th><th>Progresso</th><th>Prazo</th><th>Ação</th></tr></thead><tbody>${goals.map(g=>`<tr><td><button class="btn ghost sm" data-route="/app/people/${g.employee_id}">${esc(g.employee)}</button></td><td>${esc(g.title)}</td><td><b>${esc(g.actual)} / ${esc(g.target)}</b> ${esc(g.unit)}</td><td>${date(g.due_date)}</td><td><button class="btn alt sm" data-people-progress="${g.id}" data-actual="${g.actual}">Atualizar</button></td></tr>`).join('')}</tbody></table></section>`,'Desempenho');
}
async function viewEmployee(id){
 const d=await api('/lifecycle/employees/'+id),e=d.employee;
 return shell(`<div class="crumb" style="margin-bottom:20px"><button class="btn ghost sm" data-route="/app/people">← Pessoas</button><span>›</span>${esc(e.employee_code)}</div>`+
 `<div class="jobbanner"><div><div class="flex" style="align-items:center;gap:15px">${avatar(e.name,'big')}<div><h2>${esc(e.name)}</h2><div class="sub">${esc(e.job_title)} · ${esc(e.department)} · Admitido em ${date(e.hire_date)}</div></div></div></div>${badge(e.status)}</div>`+
 `<div class="grid2" style="margin-top:20px"><section class="panel"><div class="section-title"><h3>Jornada de integração</h3><button class="btn alt sm" data-people="new-onboarding" data-employee-id="${id}">＋ Tarefa</button></div><div style="padding:16px">${d.onboarding.map(t=>`<div class="choice-card"><div><strong>${esc(t.title)}</strong><small>${esc(t.phase)} · até ${date(t.due_date)}</small></div><button class="btn alt sm" data-people-toggle="${t.id}">${t.done?'Reabrir':'Concluir'}</button></div>`).join('')||'<p class="empty">Sem tarefas registradas.</p>'}</div></section>`+
 `<section class="panel"><div class="section-title"><h3>Aprendizagem</h3><button class="btn alt sm" data-people="assign-course" data-employee-id="${id}">＋ Curso</button></div><div style="padding:16px">${d.learning.map(x=>`<div class="choice-card"><div><strong>${esc(x.course)}</strong><small>${date(x.assigned_at)}</small></div>${x.status==='completed'?badge('completed'):`<button class="btn alt sm" data-people-complete="${x.id}">Concluir</button>`}</div>`).join('')||'<p class="empty">Nenhum curso atribuído.</p>'}</div></section>`+
 `<section class="panel"><div class="section-title"><h3>Objetivos e desempenho</h3><button class="btn alt sm" data-people="new-goal" data-employee-id="${id}">＋ Objetivo</button></div><div style="padding:16px">${d.goals.map(g=>`<div class="choice-card"><div><strong>${esc(g.title)}</strong><small>${g.actual} / ${g.target} ${esc(g.unit)}</small></div><button class="btn alt sm" data-people-progress="${g.id}" data-actual="${g.actual}">Atualizar</button></div>`).join('')}<button class="btn alt sm" data-people="new-review" data-employee-id="${id}" style="margin-top:12px">＋ Registrar avaliação</button>${d.reviews.map(r=>`<div class="choice-card"><div><strong>Avaliação ${esc(r.period)}</strong><small>${esc(r.feedback)}</small></div><span class="badge purple">${r.score}/5</span></div>`).join('')}</div></section>`+
 `<section class="panel"><div class="section-title"><h3>Carreira e mobilidade</h3></div><div style="padding:16px">${d.career.map(c=>`<div class="choice-card"><div><strong>${esc(c.kind)}</strong><small>${esc(c.description)} · ${date(c.date)}</small></div></div>`).join('')||'<p class="sub">Ainda não há eventos de carreira.</p>'}<button class="btn alt sm" style="margin-top:12px" data-people="new-career" data-employee-id="${id}">＋ Registrar movimentação</button></div></section></div>`,'Colaborador');
}
function peopleEmployeeSelect(people,selected){return selectField('employee_id','Colaborador',people.map(e=>[String(e.id),e.name]),String(selected||''));}
async function peopleAction(action,element){
 const eid=Number(element.dataset.employeeId||0);
 if(action==='create-employee')return dialog('Cadastrar colaborador',`<div class="formgrid">${field('name','Nome completo','','text','required')}${field('work_email','E-mail profissional','','email','required')}${field('department','Departamento','Pessoas')}${field('job_title','Cargo')}${field('hire_date','Data de admissão',new Date().toISOString().slice(0,10),'date','required')}</div>`,'Salvar colaborador',async f=>{await api('/lifecycle/employees',{method:'POST',body:f});toast('Colaborador cadastrado com sucesso.')});
 if(action==='new-course')return dialog('Criar curso',`<div class="formgrid">${field('title','Título do curso','','text','required')}${field('skill','Competência relacionada')}${field('duration_hours','Duração em horas','2','number','min="0.5" step="0.5"')}</div>`,'Criar curso',async f=>{await api('/lifecycle/courses',{method:'POST',body:{...f,duration_hours:Number(f.duration_hours)}});toast('Curso criado.')});
 if(action==='assign-course'){
   const [people,courses]=await Promise.all([api('/lifecycle/employees'),api('/lifecycle/courses')]);
   return dialog('Atribuir trilha de aprendizagem',`${peopleEmployeeSelect(people,eid)}${selectField('course_id','Curso',courses.map(c=>[String(c.id),c.title]))}`,'Atribuir',async f=>{await api('/lifecycle/enrollments',{method:'POST',body:{employee_id:Number(f.employee_id),course_id:Number(f.course_id)}});toast('Curso atribuído.')});
 }
 if(action==='new-onboarding')return dialog('Nova tarefa de integração',`${field('title','Tarefa','','text','required')}${selectField('phase','Etapa',['Pré-admissão','Dia 1','Primeira semana','Primeiro mês','Primeiros 90 dias'])}${field('due_date','Prazo','','date')}`,'Criar tarefa',async f=>{await api(`/lifecycle/employees/${eid}/onboarding`,{method:'POST',body:{...f,due_date:f.due_date||null}});toast('Tarefa criada.')});
 if(action==='new-goal'){
  const people=await api('/lifecycle/employees');
  return dialog('Objetivo mensurável',`<div class="formgrid">${peopleEmployeeSelect(people,eid)}${field('title','Objetivo','','text','required')}${field('target_value','Meta quantitativa','10','number','min="0.01" step="0.01"')}${field('metric_unit','Unidade','entregas')}${field('due_date','Prazo',new Date().toISOString().slice(0,10),'date','required')}</div>`,'Criar objetivo',async f=>{const id=Number(f.employee_id);await api(`/lifecycle/employees/${id}/goals`,{method:'POST',body:{title:f.title,target_value:Number(f.target_value),metric_unit:f.metric_unit,due_date:f.due_date}});toast('Meta registrada.')});
 }
 if(action==='new-review')return dialog('Avaliação estruturada',`${field('period','Período','2026-T4','text','required')}${field('results','Resultados (1–5)','3','number','min="1" max="5"')}${field('collaboration','Colaboração (1–5)','3','number','min="1" max="5"')}${areaField('feedback','Feedback observado')}`,'Registrar avaliação',async f=>{const r=await api(`/lifecycle/employees/${eid}/reviews`,{method:'POST',body:{period:f.period,criteria:[{name:'Resultados',weight:2,score:Number(f.results)},{name:'Colaboração',weight:1,score:Number(f.collaboration)}],feedback:f.feedback}});toast(`Avaliação registrada: ${r.score}/5 — leitura descritiva.`)});
 if(action==='new-career')return dialog('Registrar movimentação',`${selectField('kind','Tipo',[['promotion','Promoção'],['transfer','Transferência'],['recognition','Reconhecimento'],['other','Outro']])}${field('effective_on','Data',new Date().toISOString().slice(0,10),'date')}${areaField('description','Descrição')}`,'Registrar evento',async f=>{await api(`/lifecycle/employees/${eid}/career`,{method:'POST',body:f});toast('Evento de carreira registrado.')});
}
document.addEventListener('click',async e=>{
 const t=e.target.closest('[data-people],[data-people-toggle],[data-people-complete],[data-people-progress]');if(!t)return;
 e.preventDefault();try{
  if(t.dataset.people){await peopleAction(t.dataset.people,t);return}
  if(t.dataset.peopleToggle){await api(`/lifecycle/onboarding/${Number(t.dataset.peopleToggle)}/toggle`,{method:'POST'});toast('Tarefa atualizada.');return render()}
  if(t.dataset.peopleComplete){await api(`/lifecycle/enrollments/${Number(t.dataset.peopleComplete)}/complete`,{method:'POST'});toast('Conclusão registrada.');return render()}
  if(t.dataset.peopleProgress){const id=Number(t.dataset.peopleProgress);return dialog('Atualizar progresso da meta',field('actual_value','Resultado observado',t.dataset.actual||0,'number','min="0" step="0.01"'),'Atualizar resultado',async f=>{await api(`/lifecycle/goals/${id}/progress`,{method:'POST',body:{actual_value:Number(f.actual_value)}});toast('Progresso atualizado.')});}
 }catch(err){toast(err.message,true)}
});


// v0.5 — employee lifecycle capabilities with real persisted APIs.
const progressBar=value=>`<div class="progress-track" role="progressbar" aria-valuenow="${Math.max(0,Math.min(100,Number(value)||0))}" aria-valuemin="0" aria-valuemax="100"><span style="width:${Math.max(0,Math.min(100,Number(value)||0))}%"></span></div>`;
function emptyState(heading,body){return `<div class="empty enriched-empty"><div class="empty-symbol">✦</div><h3>${esc(heading)}</h3><p>${esc(body)}</p></div>`}

async function viewDevelopment(){
 const [plans,people,insights]=await Promise.all([api('/workforce/plans'),api('/lifecycle/employees'),api('/workforce/insights')]);
 const active=plans.filter(p=>p.status==='active');const completed=plans.filter(p=>p.status==='completed');
 return shell(headline('Planos de desenvolvimento','Competências, objetivos de aprendizagem e evidências acompanhadas ao longo do tempo.',`<button class="btn" data-pdi-create="1">＋ Novo PDI</button>`)+
 `<div class="insight-intro"><div><span class="eyebrow">Ciclo de desenvolvimento</span><h2>Da intenção à prática.</h2><p>Uma evolução é acompanhada por atividades concluídas e evidências registradas. A conclusão das ações não é prova isolada de ganho de competência.</p></div><div class="intro-mark">✳</div></div>`+
 `<div class="stats">${metric('◎','Planos cadastrados',plans.length,'Planos no contexto da equipe')}${metric('↗','Em execução',active.length,'Atividades acompanhadas')}${metric('✓','Finalizados',completed.length,'Todas as ações concluídas')}${metric('◈','Colaboradores',people.length,'Pessoas com acesso no escopo')}</div>`+
 `<div class="development-grid">${plans.map(p=>`<article class="panel development-card"><div class="flex between"><span class="badge purple">${esc(p.competency||'Competência')}</span>${badge(p.status)}</div><h3>${esc(p.title)}</h3><p class="sub small">${esc(p.employee)} · até ${date(p.due_date)}</p><p class="plan-goal">${esc(p.goal)}</p><div class="flex between"><span class="small sub">Progresso verificável</span><strong>${p.progress}%</strong></div>${progressBar(p.progress)}<div class="plan-actions">${p.actions.map((a,i)=>`<button ${p.status==='archived'?'disabled':''} class="plan-action ${a.done?'is-done':''}" data-plan-action="${p.id}" data-plan-index="${i}" data-plan-done="${a.done?'1':'0'}"><span class="plan-check">${a.done?'✓':'○'}</span><span>${esc(a.title)}${a.evidence?`<small>⤷ ${esc(a.evidence)}</small>`:''}</span></button>`).join('')}</div>${p.status!=='archived'?`<button class="btn ghost sm" data-plan-archive="${p.id}">Arquivar plano</button>`:''}</article>`).join('')||emptyState('Primeiro plano de desenvolvimento','Crie um PDI, atribua atividades e acompanhe cada evidência.')}</div>`,'Planos de desenvolvimento');
}
async function viewLeave(){
 const [rows,people]=await Promise.all([api('/workforce/leaves'),api('/lifecycle/employees')]);
 const pending=rows.filter(x=>x.status==='pending');
 return shell(headline('Ausências e férias','Solicitações, conflitos de datas e aprovações com histórico auditável.',`<button class="btn" data-leave-create="1">＋ Nova solicitação</button>`)+
 `<div class="stats">${metric('▧','Solicitações',rows.length,'Histórico do workspace')}${metric('⌛','Aguardando decisão',pending.length,'Fila de aprovação')}${metric('✓','Aprovadas',rows.filter(x=>x.status==='approved').length,'Períodos autorizados')}${metric('⨯','Recusadas',rows.filter(x=>x.status==='rejected').length,'Decisões registradas')}</div>`+
 `<div class="panel table-wrap"><div class="section-title"><div><h3>Solicitações de afastamento</h3><p>Dias corridos; saldo e regras legais não são calculados</p></div><span class="badge purple">${rows.length} registros</span></div><table class="table"><thead><tr><th>Colaborador</th><th>Natureza</th><th>Período</th><th>Dias</th><th>Status</th><th>Decisão</th></tr></thead><tbody>${rows.map(x=>`<tr><td class="jobtitle">${esc(x.employee)}<small>${esc(x.department)}</small></td><td>${badge(x.kind)}</td><td>${date(x.starts_on)} – ${date(x.ends_on)}</td><td><strong>${x.days}</strong></td><td>${badge(x.status)}</td><td>${x.status==='pending'&&['admin','manager'].includes(state.user.role)?`<div class="flex"><button class="btn sm" data-leave-decision="${x.id}" data-decision="approved">Aprovar</button><button class="btn alt sm" data-leave-decision="${x.id}" data-decision="rejected">Recusar</button></div>`:'—'}</td></tr>`).join('')||'<tr><td colspan="6">'+emptyState('Nenhuma solicitação','Registre uma ausência ou período de férias para iniciar o fluxo.')+'</td></tr>'}</tbody></table></div>`,'Ausências e férias');
}
async function viewInsights(){
 const [i,base]=await Promise.all([api('/workforce/insights'),api('/lifecycle/analytics')]);
 const pc=i.development_completion;const pct=pc.denominator?Math.round(pc.numerator/pc.denominator*100):0;
 return shell(headline('People Analytics','Painéis com população, denominadores e critérios explícitos de interpretação.')+
 `<div class="insight-intro insights-hero"><div><span class="eyebrow">Inteligência de pessoas</span><h2>Evidências antes de suposições.</h2><p>Indicadores descritivos para decisões responsáveis. Recortes pequenos são ocultados para reduzir exposição de indivíduos.</p></div><div class="intro-mark">◉</div></div>`+
 `<div class="stats">${metric('♙','Pessoas ativas',i.active,`de ${i.population} registros`)}${metric('⌛','Ausências em análise',i.pending_leaves,'Decisões aguardadas')}${metric('▤','PDIs em andamento',i.plan_count-i.completed_plans,'Planos não finalizados')}${metric('✓','PDIs concluídos',`${pc.numerator}/${pc.denominator}`,'Atividades executadas')}</div>`+
 `<div class="grid2"><section class="panel"><div class="section-title"><div><h3>Execução de planos individuais</h3><p>Planos concluídos sobre o total cadastrado</p></div><strong>${pc.denominator?pct+'%':'Sem base'}</strong></div><div class="metric-details">${progressBar(pct)}<div class="formula">Numerador: <b>${pc.numerator}</b> · Denominador: <b>${pc.denominator}</b></div><p class="sub small">${esc(pc.interpretation)}</p></div></section><section class="panel"><div class="section-title"><div><h3>Colaboradores ativos por departamento</h3><p>Supressão de células com menos de cinco registros</p></div></div><div class="metric-details">${i.departments.map(d=>`<div class="metric-line"><span>${esc(d.name)}</span><strong>${d.suppressed?'Dado restrito':fmt(d.count)}</strong></div>`).join('')||'<p class="sub">Nenhuma informação neste período.</p>'}</div></section></div>`+
 `<section class="panel methodology"><div class="section-title"><h3>Metodologia e qualidade de decisão</h3><span class="badge purple">Transparência</span></div><div class="method-grid"><div><span class="eyebrow">Origem</span><h3>Registros persistentes</h3><p>A contagem deriva de registros da própria empresa na base, nunca de valores fixos para apresentação.</p></div><div><span class="eyebrow">Privacidade</span><h3>Supressão de grupos pequenos</h3><p>Faixas com menos de cinco pessoas não revelam a contagem específica.</p></div><div><span class="eyebrow">Interpretação</span><h3>Sem inferir causalidade</h3><p>As métricas não demonstram eficácia causal de treinamentos, qualidade pessoal ou risco individual.</p></div></div></section>`,'People Analytics');
}
async function viewSecurity(){
 const sessions=await api('/auth/sessions');
 return shell(headline('Segurança da conta','Revise sessões abertas e encerre acessos de outros dispositivos.')+
 `<div class="grid2"><section class="panel"><div class="section-title"><h3>Sessões autenticadas</h3><span class="badge green">Cookie HttpOnly</span></div><div class="metric-details">${sessions.map(s=>`<div class="choice-card"><div><strong>${s.current?'Sessão deste dispositivo':'Outra sessão autenticada'}</strong><small>Expira em: ${date(s.expires_at)} · ID ${esc(s.id)}</small></div>${s.current?'<span class="badge green">Atual</span>':'<span class="badge yellow">Outra</span>'}</div>`).join('')}<button class="btn" data-session-revoke="1">Encerrar outras sessões</button></div></section><section class="panel"><div class="section-title"><h3>Camadas de proteção</h3></div><div class="metric-details"><div class="choice-card"><span>Proteção CSRF ligada à sessão</span><span class="badge green">Ativa</span></div><div class="choice-card"><span>Limite de tentativas de acesso</span><span class="badge green">Ativo</span></div><div class="choice-card"><span>Dados segregados por empresa</span><span class="badge green">Ativo</span></div><p class="note" style="margin-top:15px">A versão demonstrativa não oferece MFA/SSO. Evite usar dados sensíveis reais antes de uma auditoria independente e implantação com HTTPS.</p></div></section></div>`,'Segurança da conta');
}

document.addEventListener('click',async e=>{
 const t=e.target.closest('[data-pdi-create],[data-plan-action],[data-plan-archive],[data-leave-create],[data-leave-decision],[data-session-revoke]');if(!t)return;
 e.preventDefault();try{
  if(t.dataset.pdiCreate){
    const people=await api('/lifecycle/employees');
    return dialog('Novo plano de desenvolvimento',`<div class="formgrid">${peopleEmployeeSelect(people)}${field('title','Título','Desenvolver liderança','text','required')}${field('competency','Competência alvo','Liderança')}${field('due_date','Prazo',new Date(Date.now()+90*86400000).toISOString().slice(0,10),'date','required')}${areaField('goal','Objetivo observável','Aplicar técnicas de comunicação em reuniões e registrar evidências.')}${areaField('actions','Atividades (uma por linha)','Realizar capacitação\nAplicar em situação de trabalho\nReceber devolutiva estruturada')}</div>`,'Criar PDI',async f=>{
      await api('/workforce/plans',{method:'POST',body:{employee_id:Number(f.employee_id),title:f.title,competency:f.competency,goal:f.goal,due_date:f.due_date,actions:f.actions.split(/\n/).map(v=>v.trim()).filter(Boolean)}});toast('Plano criado e salvo no banco.');
    },{wide:true})
  }
  if(t.dataset.planAction){let id=Number(t.dataset.planAction),index=Number(t.dataset.planIndex),done=t.dataset.planDone!=='1';
    return dialog(done?'Registrar evidência':'Reabrir atividade',done?areaField('evidence','Evidência ou referência observável',''):'<p>Deseja reabrir esta atividade e recalcular o progresso?</p>',done?'Concluir atividade':'Reabrir',async f=>{await api(`/workforce/plans/${id}/action`,{method:'POST',body:{index,done,evidence:f.evidence||''}});toast('Atividade atualizada com auditoria.')});
  }
  if(t.dataset.planArchive){return confirmAction('Arquivar PDI','O plano ficará disponível para consulta, sem novas alterações.','Arquivar',async()=>{await api(`/workforce/plans/${Number(t.dataset.planArchive)}/archive`,{method:'POST'});toast('PDI arquivado.')})}
  if(t.dataset.leaveCreate){const people=await api('/lifecycle/employees');return dialog('Solicitar ausência ou férias',`<div class="formgrid">${peopleEmployeeSelect(people)}${selectField('kind','Natureza',[['vacation','Férias'],['personal','Ausência pessoal'],['medical','Saúde'],['other','Outro']])}${field('starts_on','Início','','date','required')}${field('ends_on','Término','','date','required')}${areaField('reason','Observações (não inclua dados médicos sensíveis)')}</div><p class="note" style="margin-top:14px">Fluxo demonstrativo de aprovação. Não calcula saldo de férias nem folha.</p>`,'Registrar pedido',async f=>{await api('/workforce/leaves',{method:'POST',body:{...f,employee_id:Number(f.employee_id)}});toast('Pedido registrado e encaminhado para aprovação.')})}
  if(t.dataset.leaveDecision){let id=Number(t.dataset.leaveDecision),decision=t.dataset.decision;return dialog(decision==='approved'?'Aprovar solicitação':'Recusar solicitação',areaField('comment','Observação para auditoria'),'Registrar decisão',async f=>{await api(`/workforce/leaves/${id}/decide`,{method:'POST',body:{decision,comment:f.comment}});toast('Decisão registrada no histórico.')})}
  if(t.dataset.sessionRevoke){return confirmAction('Encerrar sessões antigas','Todas as sessões desta conta, exceto a atual, serão encerradas.','Encerrar outras sessões',async()=>{let r=await api('/auth/sessions/revoke-others',{method:'POST'});toast(`${r.revoked} sessão(ões) encerrada(s).`)})}
 }catch(err){toast(err.message,true)}
});
